/**
 * Contact Enquiry Forms -- section behaviour.
 *
 * GENERATED by tools/uew from contact/section-02-forms.html. Do not edit by hand.
 *
 * The section's original script bodies are reproduced verbatim inside
 * uewRun(). What is added around them is the Elementor lifecycle: widgets are
 * injected into the editor canvas long after DOMContentLoaded, so a bare IIFE
 * would query an element that does not exist yet and the section would look
 * "broken" in the editor. Registering on frontend/element_ready fixes that, and
 * the data-uew-ready latch keeps a double call harmless.
 */
( function () {
	'use strict';

	var ROOT_SELECTOR = "#umoya-contact-forms";
	var WIDGET_NAME = "umoya-ct-forms";

	function uewRun() {
		(function(){
		  'use strict';

		  var section = document.getElementById('umoya-contact-forms');
		  if (!section || section.getAttribute('data-ready') === 'true') return;
		  section.setAttribute('data-ready', 'true');

		  /* Shared with every other Umoya form — one queue, one endpoint. */
		  var PENDING_KEY = 'umoyaPendingBackups';
		  var PENDING_MAX_AGE = 1000 * 60 * 60 * 24 * 3;
		  var DEFAULT_ENDPOINT = '/wp-json/umoya/v1/submissions';

		  function isValidEmail(v){ return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v); }

		  function getCookie(name){
		    var parts = document.cookie ? document.cookie.split('; ') : [];
		    for (var i = 0; i < parts.length; i += 1) {
		      var item = parts[i].split('=');
		      if (item[0] === name) return decodeURIComponent(item.slice(1).join('='));
		    }
		    return '';
		  }

		  function createSubmissionId(){
		    if (window.crypto && typeof window.crypto.randomUUID === 'function') return window.crypto.randomUUID();
		    return 'umoya-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 12);
		  }

		  /* ── The localStorage queue is shared, so these live outside wireForm ── */
		  function getPendingBackups(){
		    try {
		      return JSON.parse(window.localStorage.getItem(PENDING_KEY) || '[]').filter(function(item){
		        return item && (!item.queuedAt || Date.now() - item.queuedAt < PENDING_MAX_AGE);
		      });
		    } catch (ignore) { return []; }
		  }

		  function savePendingBackups(items){
		    try { window.localStorage.setItem(PENDING_KEY, JSON.stringify(items.slice(-8))); } catch (ignore) {}
		  }

		  function queuePendingBackup(payload){
		    payload.hubspotAlreadySent = true;
		    payload.queuedAt = Date.now();
		    var items = getPendingBackups();
		    items.push(payload);
		    savePendingBackups(items);
		  }

		  function flushPendingBackups(){
		    var items = getPendingBackups();
		    if (!items.length) return;
		    var remaining = items.slice();

		    items.forEach(function(item){
		      fetch(DEFAULT_ENDPOINT, {
		        method: 'POST',
		        headers: { 'Content-Type': 'application/json' },
		        credentials: 'same-origin',
		        body: JSON.stringify(item)
		      }).then(function(res){
		        if (!res.ok) return;
		        remaining = remaining.filter(function(e){ return e.submissionId !== item.submissionId; });
		        savePendingBackups(remaining);
		      }).catch(function(){});
		    });
		  }

		  /*
		   * Both panels submit identically, so the whole submit path is written once
		   * and instantiated twice. cfg carries only what actually differs: the
		   * elements, the field map, and the success wording.
		   */
		  function wireForm(cfg){
		    var form = document.getElementById(cfg.formId);
		    if (!form) return;

		    var btn = document.getElementById(cfg.btnId);
		    var originalText = btn ? btn.textContent : 'Send';
		    var submitting = false;

		    function value(name){
		      var f = form.elements[name];
		      return f ? String(f.value || '').trim() : '';
		    }

		    function setHidden(name, v){
		      var f = form.elements ? form.elements[name] : null;
		      if (f) f.value = v || '';
		    }

		    /*
		     * Panel 2 shows one "Full name" box but HubSpot stores firstname and
		     * lastname. Split on the FIRST space: everything before it is the given
		     * name, the remainder is the family name, so compound surnames such as
		     * "van der Merwe" survive intact. A single word leaves lastname empty,
		     * which HubSpot accepts.
		     */
		    function syncFullName(){
		      if (!cfg.fullNameId) return;
		      var el = document.getElementById(cfg.fullNameId);
		      if (!el) return;
		      var whole = String(el.value || '').trim().replace(/\s+/g, ' ');
		      var cut = whole.indexOf(' ');
		      setHidden('FNAME', cut === -1 ? whole : whole.slice(0, cut));
		      setHidden('LNAME', cut === -1 ? '' : whole.slice(cut + 1));
		    }

		    function syncTrackingFields(){
		      setHidden('hutk', getCookie('hubspotutk'));
		      setHidden('pageUri', window.location.href);
		      setHidden('pageName', document.title || 'Umoya Contact');
		    }

		    function identifyHubSpotVisitor(){
		      var email = value('EMAIL');
		      if (!email || !isValidEmail(email)) return;
		      window._hsq = window._hsq || [];
		      window._hsq.push(['identify', { email: email }]);
		      window._hsq.push(['trackPageView']);
		    }

		    function buildHubSpotPayload(){
		      syncFullName();
		      syncTrackingFields();

		      var fields = [];
		      Object.keys(cfg.fieldMap).forEach(function(name){
		        var v = value(name);
		        if (v) fields.push({ name: cfg.fieldMap[name], value: v });
		      });

		      var context = {
		        pageUri: window.location.href,
		        pageName: document.title || 'Umoya Contact'
		      };
		      var hutk = getCookie('hubspotutk');
		      if (hutk) context.hutk = hutk;

		      var payload = { fields: fields, context: context };

		      var consentText = (form.getAttribute('data-hubspot-consent-text') || '').trim();
		      if (consentText) {
		        payload.legalConsentOptions = { consent: { consentToProcess: true, text: consentText } };
		      }
		      return payload;
		    }

		    function buildBackupPayload(){
		      var hs = buildHubSpotPayload();
		      var raw = {};
		      Object.keys(cfg.fieldMap).forEach(function(n){ raw[n] = value(n); });

		      var consentBox = form.querySelector('#' + cfg.consentId);
		      raw.consent_to_process = consentBox && consentBox.checked ? 'yes' : 'no';

		      /* Only panel 1 offers a marketing opt-in; panel 2 has none. */
		      if (cfg.marketingId) {
		        var marketingBox = form.querySelector('#' + cfg.marketingId);
		        raw.marketing_opt_in = marketingBox && marketingBox.checked ? 'yes' : 'no';
		      }

		      return {
		        submissionId: createSubmissionId(),
		        source: (form.getAttribute('data-umoya-form-source') || '').trim(),
		        hubspotPortalId: (form.getAttribute('data-hubspot-portal-id') || '').trim(),
		        hubspotFormId: (form.getAttribute('data-hubspot-form-id') || '').trim(),
		        consentText: (form.getAttribute('data-hubspot-consent-text') || '').trim(),
		        hutk: getCookie('hubspotutk'),
		        pageUri: window.location.href,
		        pageName: document.title || 'Umoya Contact',
		        rawFields: raw,
		        fields: hs.fields,
		        context: hs.context
		      };
		    }

		    function submitToHubSpot(){
		      var portalId = (form.getAttribute('data-hubspot-portal-id') || '').trim();
		      var formId = (form.getAttribute('data-hubspot-form-id') || '').trim();
		      if (!portalId || !formId) return Promise.reject(new Error('HubSpot is not configured yet.'));

		      return fetch('https://api.hsforms.com/submissions/v3/integration/submit/' + encodeURIComponent(portalId) + '/' + encodeURIComponent(formId), {
		        method: 'POST',
		        headers: { 'Content-Type': 'application/json' },
		        body: JSON.stringify(buildHubSpotPayload())
		      }).then(function(res){
		        return res.text().then(function(text){
		          var data = null;
		          if (text) { try { data = JSON.parse(text); } catch (ignore) {} }
		          if (!res.ok) {
		            throw new Error(data && (data.message || data.error) ? (data.message || data.error) : 'HubSpot could not receive the message.');
		          }
		          return data;
		        });
		      });
		    }

		    function submitToWordPress(payload){
		      var endpoint = (form.getAttribute('data-wordpress-backup-endpoint') || DEFAULT_ENDPOINT).trim();
		      return fetch(endpoint, {
		        method: 'POST',
		        headers: { 'Content-Type': 'application/json' },
		        credentials: 'same-origin',
		        body: JSON.stringify(payload)
		      }).then(function(res){
		        return res.text().then(function(text){
		          var data = null;
		          if (text) { try { data = JSON.parse(text); } catch (ignore) {} }
		          if (!res.ok || !data || data.saved !== true) {
		            throw new Error(data && data.message ? data.message : 'WordPress could not save the message.');
		          }
		          return data;
		        });
		      });
		    }

		    function clearError(){
		      var existing = form.querySelector('.ct-f-error');
		      if (existing && existing.parentNode) existing.parentNode.removeChild(existing);
		    }

		    function showSuccess(){
		      if (!btn) return;
		      clearError();
		      btn.textContent = cfg.successText;
		      btn.disabled = true;
		      btn.style.background = '#708238';
		      btn.style.borderColor = '#708238';
		      btn.style.opacity = '1';
		    }

		    function showError(msg){
		      submitting = false;
		      if (btn) {
		        btn.textContent = originalText;
		        btn.disabled = false;
		        btn.style.opacity = '1';
		      }
		      clearError();
		      var err = document.createElement('p');
		      err.className = 'ct-f-error';
		      err.setAttribute('role', 'status');
		      err.textContent = msg;
		      if (btn && btn.parentNode) btn.parentNode.appendChild(err);
		      window.setTimeout(function(){
		        if (err.parentNode) err.parentNode.removeChild(err);
		      }, 9000);
		    }

		    syncTrackingFields();
		    window.setTimeout(syncTrackingFields, 1500);

		    form.addEventListener('submit', function(e){
		      e.preventDefault();
		      if (submitting) return;

		      syncFullName();
		      syncTrackingFields();
		      identifyHubSpotVisitor();

		      var required = form.querySelectorAll('[required]');
		      var valid = true;

		      Array.prototype.forEach.call(required, function(f){
		        if (!String(f.value || '').trim()) {
		          valid = false;
		          f.style.borderColor = '#D97E53';
		          f.style.boxShadow = '0 0 0 3px rgba(217,126,83,.12)';
		        } else {
		          f.style.borderColor = '';
		          f.style.boxShadow = '';
		        }
		      });

		      var emailField = form.querySelector('[name="EMAIL"]');
		      if (emailField && emailField.value && !isValidEmail(emailField.value)) {
		        valid = false;
		        emailField.style.borderColor = '#D97E53';
		        emailField.style.boxShadow = '0 0 0 3px rgba(217,126,83,.12)';
		      }

		      /* POPIA — the required consent box must be ticked */
		      var consentField = form.querySelector('#' + cfg.consentId);
		      if (consentField && !consentField.checked) {
		        valid = false;
		        consentField.style.outline = '2px solid #D97E53';
		        consentField.style.outlineOffset = '3px';
		      }

		      if (!valid) {
		        var firstEmpty = null;
		        Array.prototype.forEach.call(required, function(f){
		          if (!firstEmpty && !String(f.value || '').trim()) firstEmpty = f;
		        });
		        if (firstEmpty) firstEmpty.focus();
		        else if (emailField && emailField.value && !isValidEmail(emailField.value)) emailField.focus();
		        else if (consentField && !consentField.checked) consentField.focus();
		        showError(consentField && !consentField.checked && !firstEmpty
		          ? 'Please tick the consent box so we may reply.'
		          : 'Please complete the required fields.');
		        return;
		      }

		      submitting = true;
		      if (btn) {
		        btn.disabled = true;
		        btn.textContent = 'Sending…';
		        btn.style.opacity = '0.7';
		      }
		      clearError();

		      var payload = buildBackupPayload();

		      /* WordPress first — it stores the lead, then forwards it to HubSpot.
		         Direct HubSpot is only the fallback. */
		      submitToWordPress(payload)
		        .then(showSuccess)
		        .catch(function(err){
		          submitToHubSpot()
		            .then(function(){ queuePendingBackup(payload); showSuccess(); })
		            .catch(function(fallbackErr){
		              showError((err.message || 'We could not save your message.') + ' ' + (fallbackErr.message || ''));
		            });
		        });
		    });

		    /* Clear validation styling as soon as the visitor corrects a field */
		    form.querySelectorAll('input, select, textarea').forEach(function(f){
		      f.addEventListener('input', function(){
		        f.style.borderColor = '';
		        f.style.boxShadow = '';
		      });
		      f.addEventListener('change', function(){
		        f.style.borderColor = '';
		        f.style.boxShadow = '';
		      });
		    });

		    var consentEl = form.querySelector('#' + cfg.consentId);
		    if (consentEl) {
		      consentEl.addEventListener('change', function(){
		        consentEl.style.outline = '';
		        consentEl.style.outlineOffset = '';
		      });
		    }

		    if (cfg.fullNameId) {
		      var nameEl = document.getElementById(cfg.fullNameId);
		      if (nameEl) nameEl.addEventListener('input', syncFullName);
		    }
		  }

		  /* Panel 1 — same field set as the Founder's Circle form. */
		  wireForm({
		    formId: 'ctPlanForm',
		    btnId: 'ctPlanBtn',
		    consentId: 'ctConsent',
		    marketingId: 'ctMarketing',
		    successText: 'Received — We’ll Be in Touch Soon',
		    fieldMap: {
		      MERGE1: 'salutation',
		      FNAME:  'firstname',
		      LNAME:  'lastname',
		      EMAIL:  'email',
		      PHONE:  'phone',
		      MERGE2: 'country',
		      MERGE3: 'city',
		      MERGE4: 'preferred_travel_season',   /* carries MONTH */
		      MERGE5: 'preferred_travel_year',
		      MERGE6: 'party_size',                /* "How many guests…" */
		      MERGE7: 'founders_circle_message'
		    }
		  });

		  /* Panel 2 — lean routing form. FNAME/LNAME are the hidden split fields. */
		  wireForm({
		    formId: 'ctGeneralForm',
		    btnId: 'ctGeneralBtn',
		    consentId: 'ctGenConsent',
		    fullNameId: 'ctGenName',
		    successText: 'Message Sent — Thank You',
		    fieldMap: {
		      FNAME:  'firstname',
		      LNAME:  'lastname',
		      EMAIL:  'email',
		      MERGE3: 'organization',
		      MERGE2: 'enquiry_type',
		      MERGE7: 'founders_circle_message'
		    }
		  });

		  window.setTimeout(flushPendingBackups, 1200);

		  /* ── Scroll reveal ────────────────────────────────────────── */
		  var rvEls = section.querySelectorAll('.ct-f-rv');
		  if ('IntersectionObserver' in window) {
		    var obs = new IntersectionObserver(function(entries){
		      entries.forEach(function(e){
		        if (e.isIntersecting) { e.target.classList.add('ct-f-on'); obs.unobserve(e.target); }
		      });
		    }, { threshold: 0.05 });
		    Array.prototype.forEach.call(rvEls, function(el){ obs.observe(el); });
		  } else {
		    Array.prototype.forEach.call(rvEls, function(el){ el.classList.add('ct-f-on'); });
		  }
		}());
	}

	function uewInit( scope ) {
		var context = scope && scope.length ? scope[ 0 ] : ( scope || document );
		var root = context.querySelector ? context.querySelector( ROOT_SELECTOR ) : null;

		if ( ! root && context !== document && context.matches && context.matches( ROOT_SELECTOR ) ) {
			root = context;
		}
		if ( ! root ) {
			root = document.querySelector( ROOT_SELECTOR );
		}
		if ( ! root ) {
			return;
		}
		if ( root && root.getAttribute( 'data-uew-ready' ) === '1' ) {
			return;
		}
		if ( root ) {
			root.setAttribute( 'data-uew-ready', '1' );
		}

		uewRun();
	}

	function uewRegister() {
		if ( ! window.elementorFrontend || ! window.elementorFrontend.hooks ) {
			return false;
		}
		window.elementorFrontend.hooks.addAction( 'frontend/element_ready/' + WIDGET_NAME + '.default', uewInit );
		return true;
	}

	if ( ! uewRegister() ) {
		// Elementor fires this through jQuery, not as a native DOM event, so a
		// plain addEventListener would never hear it.
		if ( window.jQuery ) {
			window.jQuery( window ).on( 'elementor/frontend/init', uewRegister );
		} else {
			window.addEventListener( 'elementor/frontend/init', uewRegister );
		}
	}

	// Plain page load (and any context where Elementor's frontend never boots).
	if ( document.readyState === 'loading' ) {
		document.addEventListener( 'DOMContentLoaded', function () {
			uewInit( document );
		} );
	} else {
		uewInit( document );
	}
}() );
